import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 9 — Review at Scale","description":"","frontmatter":{"source":"weeks/09-review-at-scale/README.md"},"headers":[],"relativePath":"weeks/09-review-at-scale/index.md","filePath":"weeks/09-review-at-scale/index.md"}'),n={name:"weeks/09-review-at-scale/index.md"};function s(i,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="week-9--review-at-scale" tabindex="-1">Week 9 — Review at Scale <a class="header-anchor" href="#week-9--review-at-scale" aria-label="Permalink to &quot;Week 9 — Review at Scale&quot;">​</a></h1><blockquote><p>When agents write code faster than people can read it, review becomes both the bottleneck and the control: measure your reviewers, human and AI, against known defects, and turn the checks machines do well into gates.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Reading and reading response on Canvas · submit the week 8 assignment (the Seminar opens with its quiz) · <strong>M1</strong>, peer evaluation 1 and PR-round preparation are due · graduate presentation: post one question (<a href="./../../graduate/paper-presentations.html#questions-from-the-class">how</a>)</td></tr><tr><td><strong>Seminar</strong></td><td>Due-date quiz on the week 8 assignment (7 min, 🔴 AI off) · talk: reviewing AI-authored PRs, AI reviewers in production, static analysis, CI gates, comments people act on (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-09.html" target="_blank" rel="noreferrer">slides</a>) · reading discussion or a graduate paper · demo: one PR, a human and an AI review side by side · Lab preview, and <strong>the PR round opens</strong> with the ring</td></tr><tr><td><strong>Lab</strong></td><td><a href="./lab.html#lab--review-five-prs-then-review-the-reviewer-75-min">The review lab</a>: in a fresh copy of <code>roomly</code> at its first commit, open five patches as PRs and review them yourself (🔴 AI off); then an AI reviewer on the same PRs, and CI gates on your team fork. <strong>Checkoff:</strong> your own reviews of at least three PRs</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: the <a href="./lab.html#assignment--human-versus-ai-review-and-a-ci-gate">assignment</a> (the comparison with a confusion table; a CI gate on the team fork), with your reviews frozen earlier, before the defect key is released · your <strong>PR-round PR</strong> on your target fork (<a href="./../../project/pr-round.html#week-9-open-your-pr">PR round</a>)</td></tr><tr><td><strong>AI use this week</strong></td><td>🔴 AI off: your reviews and every comment you sign, your PR-round description, the quiz, the reading response · 🟢 AI on: the AI reviewer, CI configuration, tabulating scores, your PR-round code</td></tr><tr><td><strong>Reading</strong></td><td>Chowdhury, Banik, Ferdous &amp; Shamim, <a href="https://arxiv.org/abs/2604.03196" target="_blank" rel="noreferrer">&quot;From Industry Claims to Empirical Reality&quot;</a> (MSR 2026)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>M1 is snapshotted. <a href="./../../project/pr-round.html">The PR round</a> opens: claim an <code>eswa-pr-round</code> issue on your target fork; PR due before the week 10 Seminar. Your team adds lint and CodeQL or Semgrep to the fork&#39;s CI, required on <code>main</code></td></tr><tr><td><strong>Graduate track</strong></td><td>Cihan et al. (Beko) and Tantithamthavorn et al. (Atlassian) as a pair: their cycle-time results disagree (<a href="./../../graduate/paper-presentations.html#the-papers">papers</a>). Chowdhury et al. is <a href="./../../graduate/empirical-study.html#the-replicable-list">replicable</a></td></tr><tr><td><strong>Time</strong></td><td>Meetings 2.5 h · outside about 6 h (CS [5xxx]: 7.5 h): reading 45 min, assignment 3.5 h, CI gate 1 h · plus about 4 h for your PR-round PR</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Review an AI-authored PR systematically: treat its description as claims, check them by running the code, leave located comments marked blocking or not, and decide.</li><li>Score reviewers, yourself and an <a href="./../../resources/glossary.html#ai-reviewer">AI reviewer</a>, against a defect key with <a href="./../../resources/glossary.html#precision-and-recall">precision and recall</a> and a confusion table, and explain why noise costs as much as misses.</li><li>Interpret field evidence on AI review: merge rates when only bots review, how often comments lead to changes, and why studies disagree about cycle time.</li><li>Set up required CI gates on a real fork (tests, lint, CodeQL or Semgrep), and keep workflows safe when other people&#39;s PRs run them.</li><li>Write review comments that people act on.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Minutes</th><th>What happens</th></tr></thead><tbody><tr><td>Due-date quiz</td><td>7</td><td>On the week 8 refactor (<a href="./../../assessment/quizzes.html">quizzes</a>), 🔴 AI off</td></tr><tr><td>Concept talk</td><td>25</td><td>Agent-authored PRs; AI reviewers in production; precision; static analysis and gates; comments that lead to changes (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-09.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td>Discussion or paper</td><td>20</td><td>Should an AI reviewer ever approve a PR alone? Or the Beko and Atlassian pair</td></tr><tr><td>Live demo</td><td>10</td><td>An agent-written PR (not one of the lab&#39;s five) reviewed by the instructor and by an AI, scored live</td></tr><tr><td>Lab preview and the PR round</td><td>5</td><td>The fresh-copy setup; AI off until your reviews are pushed; the ring is posted</td></tr></tbody></table><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>The <a href="./lab.html#lab--review-five-prs-then-review-the-reviewer-75-min">review lab</a> uses <code>roomly</code>&#39;s <code>review-prs/</code>: five PRs as patches, each with its &quot;author&#39;s&quot; description (claims, not facts). The patches apply only to <code>roomly</code> as shipped, so you work in a fresh copy at your repository&#39;s first commit (a new clone or a git <a href="./../../resources/glossary.html#worktree">worktree</a>). You review first, AI off; an AI reviewer follows; once your reviews are frozen, staff release the defect key and you score both. The <a href="./lab.html#assignment--human-versus-ai-review-and-a-ci-gate">assignment</a> adds a CI gate on your team fork.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p><strong>Chowdhury, Banik, Ferdous &amp; Shamim, <a href="https://arxiv.org/abs/2604.03196" target="_blank" rel="noreferrer">&quot;From Industry Claims to Empirical Reality&quot;</a></strong> (MSR 2026; free on arXiv). PRs reviewed only by code-review agents were merged 45.2% of the time, against 68.4% for human-reviewed PRs, and were abandoned more often; 12 of 13 agents had average signal ratios below 60%. It tests the industry claim that agents can handle most PRs alone.</p><p><strong>Reading response prompt</strong> (150–250 words, 🔴 AI off): State the main finding with two numbers. PRs that only a bot reviewed may differ from human-reviewed ones before any review happens: name one such difference and which way it would push the merge rates. Explain &quot;signal ratio&quot; in your own words, and why it matters as much as how many defects a reviewer finds. End with one question for the Seminar.</p><p>More: <a href="./../../resources/reading-list.html#week-9--review-at-scale">reading list, week 9</a>.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><ul><li><strong>Agent PRs get merged, then fixed.</strong> Of 567 Claude Code PRs, 83.8% were merged and 45.1% of those needed further changes (<a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">Watanabe et al.</a>); maintainers merged test-passing agent PRs 24.2 points less often than a grader accepted them (<a href="https://metr.org/notes/2026-03-10-many-swe-bench-passing-prs-would-not-be-merged-into-main/" target="_blank" rel="noreferrer">METR</a>). Green CI is where review starts.</li><li><strong>Review burden is the cost that scales:</strong> making agent PRs mergeable took 42 minutes on average in METR&#39;s 2025 study. The <a href="./../../templates/REVIEW.html">REVIEW template</a> asks for a PR small enough for one sitting, or a split.</li><li><strong>AI reviewers&#39; results disagree.</strong> At Beko, 73.8% of AI comments were resolved but PR closure time rose from 5 h 52 min to 8 h 20 min (<a href="https://arxiv.org/abs/2412.18531" target="_blank" rel="noreferrer">Cihan et al.</a>); at Atlassian, 38.7% of AI comments led to changes (humans: 44.45%) and cycle time fell 30.8% (<a href="https://arxiv.org/abs/2601.01129v2" target="_blank" rel="noreferrer">Tantithamthavorn et al.</a>).</li><li><strong>Precision is the design problem.</strong> False alarms spend everyone&#39;s attention; Copilot&#39;s reviewer deliberately says nothing on 29% of reviews (<a href="https://github.blog/ai-and-ml/github-copilot/60-million-copilot-code-reviews-and-counting/" target="_blank" rel="noreferrer">GitHub</a>).</li><li><strong>Comments that lead to changes</strong> are concise, include a code snippet, or were asked for (<a href="https://arxiv.org/abs/2508.18771" target="_blank" rel="noreferrer">Sun et al.</a>, 22,000+ comments): location, observation, consequence, fix, blocking or not.</li><li><strong>Static analysis matches known dangerous shapes,</strong> and rarely finds logic errors. LLMs can feed it: LLM-inferred taint specifications let CodeQL find 55 of 120 Java CVEs, against 27 alone (<a href="https://arxiv.org/abs/2405.17238" target="_blank" rel="noreferrer">IRIS</a>).</li><li><strong>A gate is a check that blocks merging.</strong> On old code, gate what a PR changes (a ratchet), or the gate is red forever and everyone learns to ignore it.</li><li><strong>Other people&#39;s PRs run your workflows,</strong> with your fork&#39;s secrets: in the PR round, team forks hold none.</li></ul><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>A PR has 4 known defects. A reviewer leaves 10 comments: 4 match defects (two the same one), 4 point at problems that aren&#39;t there, 2 are praise. Using the lab&#39;s counting rule, what are its precision and recall?</li><li>How would you check a PR description&#39;s &quot;no behavior change&quot;?</li><li>Name two differences between Beko and Atlassian that could explain their opposite cycle-time results.</li><li>Your fork&#39;s linter reports 2,000 warnings on <code>main</code>. How do you add a lint gate that helps rather than blocks?</li><li>Why is <code>pull_request_target</code> plus a checkout of the PR&#39;s code dangerous?</li></ol><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><ul><li><strong>The AI reviewer:</strong> CodeRabbit on a public repository first, then PR-Agent with your Gemini key (on your own <code>roomly</code> repository only), then Copilot code review at Lite effort (<a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>). If none works, report the blocker and score your own review only.</li><li><strong>No CodeQL default setup</strong> (private repository, no admin rights): run Semgrep Community Edition, and ask staff for the setting. Failing workflows: <a href="./../../resources/troubleshooting.html#ci-minutes-and-failing-workflows">troubleshooting</a>.</li></ul><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Peralta et al., <a href="https://arxiv.org/abs/2605.22534" target="_blank" rel="noreferrer">&quot;Why Are Agentic Pull Requests Merged or Rejected?&quot;</a>: only 35.7% of rejections were clear agent failures, so &quot;rejected&quot; is a noisy label for &quot;bad&quot;.</li><li>Oliveira et al., <a href="https://arxiv.org/abs/2604.23251" target="_blank" rel="noreferrer">arXiv 2604.23251</a>: in a 100+-student capstone, failed AI reviews fell from 227 to 0 after tool and instruction fixes. Pilot your bot.</li><li>Case <a href="./../../resources/case-studies.html#a8-pixelleak-helpful-agents-publish-13000-screenshots">A8</a>: agents publishing screenshots for code reviews.</li><li>Previous week: <a href="./../08-legacy-code/">Legacy Code</a>. Next week: <a href="./../10-supply-chain/">Supply Chain and Secure Code</a>.</li></ul>',23)])])}const f=t(n,[["render",s]]);export{g as __pageData,f as default};
